#!/usr/bin/env bash
# Brings a fork or copy of BridgePatcher up to date with upstream. Run by
# .github/workflows/sync-fork.yml, which explains the rules; run from a checkout
# of this repository with all branches fetched (origin/*).
#
# For the default branch and the head branch of every open upstream PR made from
# this repository: if upstream has had commits that branch is missing for more
# than MAX_AGE_DAYS, fast-forward or merge them in and push. Branches that are
# up to date, or fell behind more recently, are left alone. A branch that
# conflicts or can't be pushed is reported and skipped; the script then exits 1.
#
# Env: UPSTREAM, UPSTREAM_BRANCH, BRANCH (this repo's default branch),
#      MAX_AGE_DAYS, GITHUB_REPOSITORY, PUSH_TOKEN, GH_TOKEN (to list PRs),
#      optional FORCE=true (ignore the age), HAS_SYNC_TOKEN, GITHUB_STEP_SUMMARY.
set -euo pipefail

: "${UPSTREAM:?}" "${UPSTREAM_BRANCH:?}" "${BRANCH:?}" "${MAX_AGE_DAYS:?}" "${GITHUB_REPOSITORY:?}"
FORCE="${FORCE:-false}"
UPSTREAM_URL="${UPSTREAM_URL:-https://github.com/${UPSTREAM}.git}"
PUSH_URL="${PUSH_URL:-https://x-access-token:${PUSH_TOKEN:?}@github.com/${GITHUB_REPOSITORY}.git}"
SUMMARY="${GITHUB_STEP_SUMMARY:-/dev/null}"
max_age=$(( MAX_AGE_DAYS * 86400 ))
now=$(date +%s)
failed=0

note() { printf -- '- %s\n' "$*" | tee -a "$SUMMARY"; }
fail() { echo "::error::$*"; printf -- '- **Failed:** %s\n' "$*" >> "$SUMMARY"; failed=1; }

git config core.hooksPath /dev/null
git remote add upstream "$UPSTREAM_URL" 2>/dev/null || git remote set-url upstream "$UPSTREAM_URL"

# sync_branch <branch in this repo> <upstream branch> <label for messages>
sync_branch() {
  local branch=$1 base=$2 label=$3 head up first_missing behind since age days how err

  if ! head=$(git rev-parse -q --verify "refs/remotes/origin/${branch}^{commit}"); then
    fail "${label}: branch \`${branch}\` not found in this repository"; return
  fi
  if ! git fetch -q upstream "+refs/heads/${base}:refs/remotes/upstream/${base}"; then
    fail "${label}: could not fetch ${UPSTREAM}@${base}"; return
  fi
  up=$(git rev-parse "refs/remotes/upstream/${base}")

  behind=$(git rev-list --count "${head}..${up}")
  if [ "$behind" -eq 0 ]; then
    note "${label}: already has everything from ${UPSTREAM}@${base}."
    return
  fi

  # The branch fell behind when upstream first got a commit it doesn't have. Follow
  # upstream's first parents so a merged PR counts from when it was merged, not
  # from when its commits were written.
  first_missing=$(git rev-list --first-parent "${head}..${up}" | tail -n 1)
  since=$(git log -1 --format=%ct "$first_missing")
  age=$(( now - since ))
  days=$(( age / 86400 ))
  if [ "$age" -le "$max_age" ] && [ "$FORCE" != true ]; then
    note "${label}: behind ${UPSTREAM}@${base} for ${days} day(s), not more than ${MAX_AGE_DAYS}; leaving it alone (${behind} commit(s) waiting)."
    return
  fi

  git checkout -q --detach "$head"
  if git merge-base --is-ancestor "$head" "$up"; then
    git merge -q --ff-only "$up"
    how="fast-forwarded"
  elif git -c user.name="github-actions[bot]" \
           -c user.email="41898282+github-actions[bot]@users.noreply.github.com" \
           merge -q --no-edit -m "Merge ${UPSTREAM}@${base} into ${branch}" \
           -m "Generated by the sync-fork workflow." "$up"; then
    how="merged"
  else
    git merge --abort || git reset -q --hard
    fail "${label}: merging ${UPSTREAM}@${base} conflicts with its own commits; nothing was pushed, update it by hand"
    return
  fi

  # No force push: if someone pushed to the branch meanwhile, this is rejected and
  # the branch is tried again on the next run.
  if ! err=$(git push -q "$PUSH_URL" "HEAD:refs/heads/${branch}" 2>&1); then
    printf '%s\n' "${err//${PUSH_TOKEN:-unset}/***}" >&2
    if grep -qi 'workflow' <<< "$err"; then
      if [ "${HAS_SYNC_TOKEN:-false}" = true ]; then
        fail "${label}: FORK_SYNC_TOKEN may not change workflow files; give it the Workflows permission (or the classic \"workflow\" scope)"
      else
        fail "${label}: upstream changed files in .github/workflows, which GITHUB_TOKEN may not push; add a FORK_SYNC_TOKEN secret (see sync-fork.yml)"
      fi
    else
      fail "${label}: could not push to \`${branch}\`"
    fi
    return
  fi
  note "${label}: ${how} ${behind} commit(s) from ${UPSTREAM}@${base} ($(git rev-parse --short HEAD)); it was behind for ${days} day(s)."
}

printf '### Sync with %s\n\n' "$UPSTREAM" >> "$SUMMARY"
sync_branch "$BRANCH" "$UPSTREAM_BRANCH" "\`${BRANCH}\`"

# Open upstream PRs whose head branch lives in this repository: "<number> <head> <base>".
# The default branch was handled above; a branch used by several PRs is synced once.
repo_lc=${GITHUB_REPOSITORY,,}
if ! prs=$(gh api --paginate "repos/${UPSTREAM}/pulls?state=open&per_page=100" --jq \
    ".[] | select(.head.repo != null and (.head.repo.full_name | ascii_downcase) == \"${repo_lc}\")
         | \"\(.number) \(.head.ref) \(.base.ref)\""); then
  fail "could not list the open pull requests of ${UPSTREAM}"
  prs=""
fi
declare -A seen=(["$BRANCH"]=1)
while read -r number head_ref base_ref; do
  [ -n "${number:-}" ] || continue
  [ -z "${seen[$head_ref]:-}" ] || continue
  seen[$head_ref]=1
  sync_branch "$head_ref" "$base_ref" "PR #${number} (\`${head_ref}\`)"
done <<< "$prs"

git checkout -q --detach "refs/remotes/origin/${BRANCH}" 2>/dev/null || true
exit "$failed"
